import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第二十三卦 剥 山地剥 艮上坤下","description":"周易 - 第二十三卦 剥 山地剥 艮上坤下","frontmatter":{"title":"第二十三卦 剥 山地剥 艮上坤下","description":"周易 - 第二十三卦 剥 山地剥 艮上坤下"},"headers":[],"relativePath":"zh/classics/zhouyi/024.md","filePath":"zh/classics/zhouyi/024.md"}'),l={name:"zh/classics/zhouyi/024.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="剥" tabindex="-1">剥 <a class="header-anchor" href="#剥" aria-label="Permalink to “剥”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>不利有攸往。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>剥，剥也，柔变刚也。不利有攸往，小人长也。顺而止之，观象也。君子尚消息盈虚，天行也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>山附地上，剥；上以厚下，安宅。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>剥(爿木)以足，蔑贞凶。象曰：剥(爿木)以足，以灭下也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>剥(爿木)以辨，蔑贞凶。象曰：剥(爿木)以辨，未有与也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>剥之，无咎。象曰：剥之无咎，失上下也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>剥(爿木)以肤，凶。象曰：剥(爿木)以肤，切近灾也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>贯鱼，以宫人宠，无不利。象曰：以宫人宠，终无尤也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>硕果不食，君子得舆，小人剥庐。象曰：君子得舆，民所载也。小人剥庐，终不可用也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
